<?php
declare(strict_types=1);
return function(Router $r){
    $r->post('/platform/workspace/configure',function(){WorkspaceExchange::configure($_POST);return redirect('/platform#workspace-delivery','Workspace delivery preferences saved.');});
    $r->post('/platform/workspace/send',function(){WorkspaceExchange::send();return redirect('/platform#workspace-delivery','Encrypted workspace snapshot delivered.');});
    $r->post('/platform/workspace/preview',function(){$preview=WorkspaceExchange::preview(text_input('file',300));$_SESSION['workspace_review']=$preview;return View::render(__DIR__.'/views/workspace-review.php',['title'=>t('Review workspace replacement'),'preview'=>$preview]);});
    $r->post('/platform/workspace/apply',function(){$review=$_SESSION['workspace_review']??throw new InvalidArgumentException(t('Review a received snapshot first.'));WorkspaceExchange::apply($review,text_input('confirmation',20));unset($_SESSION['workspace_review']);return redirect('/platform#workspace-delivery','Reviewed workspace replacement completed; previous records and documents are preserved in backups.');});
    $r->get('/platform/records',fn()=>View::render(__DIR__.'/views/records-import.php',['title'=>t('Portable records')]));
    $r->post('/platform/records/map',function(){$target=text_input('target',40);PortableRecords::target($target);$format=text_input('format',20);if($format==='xlsx'){$file=$_FILES['file']??[];if(($file['error']??1)!==UPLOAD_ERR_OK)throw new InvalidArgumentException(t('Choose an XLSX file.'));$rows=SpreadsheetTransfer::read($file['tmp_name'],true);}else $rows=PortableRecords::raw(text_input('content',2097152),$format);if(!$rows)throw new InvalidArgumentException(t('Import at least one record.'));$_SESSION['portable_raw']=['target'=>$target,'rows'=>$rows];return View::render(__DIR__.'/views/record-mapping.php',['title'=>t('Map import columns'),'target'=>$target,'rows'=>$rows]);});
    $r->post('/platform/records/preview',function(){$raw=$_SESSION['portable_raw']??throw new InvalidArgumentException(t('Upload or paste records first.'));$mapping=$_POST['mapping']??[];if(!is_array($mapping))throw new InvalidArgumentException(t('Choose field mappings.'));$prepared=PortableRecords::prepare($raw['target'],$raw['rows'],$mapping,optional_id($_POST['module_id']??''));$_SESSION['portable_ready']=['target'=>$raw['target'],'rows'=>$prepared];return View::render(__DIR__.'/views/record-preview.php',['title'=>t('Review record import'),'target'=>$raw['target'],'rows'=>$prepared]);});
    $r->post('/platform/records/apply',function(){$ready=$_SESSION['portable_ready']??throw new InvalidArgumentException(t('Preview the records first.'));PortableRecords::import($ready['target'],$ready['rows']);unset($_SESSION['portable_ready'],$_SESSION['portable_raw']);return redirect('/platform','Reviewed records imported.');});
    $r->get('/platform/records/{target}/export',function($p){$target=$p['target'];PortableRecords::target($target);header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="lifeos-'.$target.'.csv"');return PortableRecords::csv($target);});
    $r->post('/platform/objects/export',function(){$contacts=$_POST['contacts']??[];$documents=$_POST['documents']??[];if(!is_array($contacts)||!is_array($documents)||(!$contacts&&!$documents))throw new InvalidArgumentException(t('Select at least one contact or document.'));$packet=SecureObjectSync::packet(text_input('peer',64),$contacts,$documents);header('Content-Type: application/json');header('Content-Disposition: attachment; filename="lifeos-encrypted-records.json"');return $packet;});
    $r->post('/platform/objects/preview',function(){if(isset($_FILES['file'])&&$_FILES['file']['error']===UPLOAD_ERR_OK){if($_FILES['file']['size']>12582912)throw new InvalidArgumentException(t('Packet exceeds 12 MiB.'));$packet=file_get_contents($_FILES['file']['tmp_name']);}else $packet=text_input('packet',12582912);$preview=SecureObjectSync::preview($packet);$_SESSION['platform_objects']=$packet;return View::render(__DIR__.'/views/objects.php',['title'=>t('Review record and attachment sync'),'preview'=>$preview]);});
    $r->post('/platform/objects/apply',function(){$choices=$_POST['choices']??[];if(!is_array($choices))throw new InvalidArgumentException(t('Choose conflict resolutions.'));SecureObjectSync::apply($_SESSION['platform_objects']??'',$choices);unset($_SESSION['platform_objects']);return redirect('/platform','Selected records synchronized; previous document versions retained.');});
    $r->post('/api/v1/mobile/tasks',function(){
        header('Content-Type: application/json');try{if(!module_enabled('Platform')||!module_enabled('Planner'))throw new InvalidArgumentException(t('Enable Devices & privacy and Planner.'));$token=ConnectivityService::authorizeApi('tasks.write');$raw=file_get_contents('php://input',false,null,0,65537);if(strlen($raw)>65536)throw new InvalidArgumentException(t('Request too large.'));$d=json_decode($raw,true,16,JSON_THROW_ON_ERROR);$rid=$d['request_id']??'';if(!is_string($rid)||!preg_match('/^[a-f0-9-]{36}$/D',$rid))throw new InvalidArgumentException(t('Send a stable request UUID.'));$bodyHash=hash('sha256',json_encode([$d['title']??null,$d['due']??null]));$id=Db::tx(function()use($d,$rid,$token,$bodyHash){$old=Db::one('SELECT * FROM platform_mobile_receipts WHERE request_id=?',[$rid]);if($old){if((int)$old['token_id']!==(int)$token['id']||$old['body_hash']!==$bodyHash)throw new InvalidArgumentException(t('Request ID was already used for a different task.'));return $old['task_id'];}$id=PlannerService::saveTask(null,$d);Db::run('INSERT INTO platform_mobile_receipts(request_id,task_id,token_id,body_hash) VALUES(?,?,?,?)',[$rid,$id,$token['id'],$bodyHash]);return $id;});return json_encode(['id'=>$id],JSON_THROW_ON_ERROR);}catch(InvalidArgumentException|JsonException $e){http_response_code(422);return json_encode(['error'=>$e->getMessage()]);}
    });
    $r->post('/platform/security',function(){
        $hash=Db::setting('pin_hash');if($hash===''||!password_verify(text_input('pin',12),$hash))throw new InvalidArgumentException(t('Set a profile PIN and enter it to change security settings.'));$seconds=int_range($_POST['idle_seconds']??'0',0,3600);if($seconds>0&&$seconds<60)throw new InvalidArgumentException(t('Auto-lock must be at least 60 seconds.'));Db::set('platform_idle_seconds',(string)$seconds);Db::set('platform_hello',isset($_POST['hello'])?'1':'0');$_SESSION['platform_activity']=time();PlatformService::audit('security-configured','Profile lock preferences updated.');return redirect('/platform','Lock preferences saved.');
    });
    $r->post('/platform/activity',function(){$_SESSION['platform_activity']=time();return '';});
    $r->get('/platform',fn()=>View::render(__DIR__.'/views/index.php',['title'=>t('Devices & privacy')]));
    $r->post('/platform/import/preview',function(){if(!module_enabled('Planner'))throw new InvalidArgumentException(t('Enable Planner.'));$format=text_input('format',20);if($format==='xlsx'){$file=$_FILES['file']??[];if(($file['error']??1)!==UPLOAD_ERR_OK)throw new InvalidArgumentException(t('Choose an XLSX file.'));$rows=SpreadsheetTransfer::read($file['tmp_name']);}else{$rows=PlatformService::preview(text_input('content',2097152),$format);}$_SESSION['platform_import']=$rows;return View::render(__DIR__.'/views/preview.php',['title'=>t('Review task import'),'rows'=>$rows]);});
    $r->post('/platform/import/apply',function(){if(!module_enabled('Planner'))throw new InvalidArgumentException(t('Enable Planner.'));$rows=$_SESSION['platform_import']??throw new InvalidArgumentException(t('Preview the import first.'));PlatformService::import($rows);unset($_SESSION['platform_import']);return redirect('/platform','Tasks imported.');});
    $r->get('/platform/export/{format}',function($p){if(!module_enabled('Planner'))throw new InvalidArgumentException(t('Enable Planner.'));$format=$p['format'];if(!in_array($format,['csv','xlsx','json'],true))throw new InvalidArgumentException(t('Choose CSV, XLSX or JSON.'));header('Content-Type: '.match($format){'csv'=>'text/csv; charset=utf-8','xlsx'=>'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',default=>'application/json'});header('Content-Disposition: attachment; filename="lifeos-tasks.'.$format.'"');return match($format){'csv'=>PlatformService::export(),'xlsx'=>SpreadsheetTransfer::write(),default=>json_encode(Db::all('SELECT title,due,status FROM tasks ORDER BY id'),JSON_THROW_ON_ERROR)};});
    $r->post('/platform/import/{id}/undo',function($p){PlatformService::undo(record_id($p['id']));return redirect('/platform','Import undone.');});
    $r->post('/platform/history/{id}/undo',function($p){PlatformService::undoEdit(record_id($p['id']));return redirect('/platform','Edit undone.');});
    $r->post('/platform/history/clear',function(){Db::tx(function(){Db::run('DELETE FROM platform_history');PlatformService::audit('history-cleared','User cleared retained edit contents.');});return redirect('/platform','Edit history cleared.');});
    $r->post('/platform/pair',function(){DeviceSyncService::pair(text_input('name',100),text_input('public_key',100));return redirect('/platform','Device paired. Verify the fingerprint on both devices.');});
    $r->post('/platform/peer/{id}/revoke',function($p){Db::run('UPDATE platform_peers SET revoked=1 WHERE id=?',[$p['id']]);PlatformService::audit('device-revoked',$p['id']);return redirect('/platform','Device revoked. Future packets from it are refused.');});
    $r->post('/platform/sync/export',function(){header('Content-Type: application/json');header('Content-Disposition: attachment; filename="lifeos-device-sync.json"');return DeviceSyncService::packet(text_input('peer',64));});
    $r->post('/platform/sync/preview',function(){$packet=text_input('packet',2097152);$preview=DeviceSyncService::preview($packet);$_SESSION['platform_packet']=$packet;return View::render(__DIR__.'/views/sync.php',['title'=>t('Review encrypted sync'),'preview'=>$preview]);});
    $r->post('/platform/sync/apply',function(){$choices=$_POST['choices']??[];if(!is_array($choices))throw new InvalidArgumentException(t('Choose conflict resolutions.'));DeviceSyncService::apply($_SESSION['platform_packet']??'',$choices);unset($_SESSION['platform_packet']);return redirect('/platform','Reviewed task sync applied.');});
    $r->post('/platform/recovery',function(){header('Content-Type: text/plain');header('Content-Disposition: attachment; filename="lifeos-device-key.recovery"');return DeviceSyncService::recovery(text_input('passphrase',200));});
    $r->post('/platform/recovery/restore',function(){DeviceSyncService::restore(text_input('blob',300),text_input('passphrase',200),text_input('fingerprint',64));return redirect('/platform','Device key recovered after fingerprint verification.');});
    $r->post('/platform/publisher',function(){PluginTrustService::trust(text_input('name',100),text_input('public_key',100));return redirect('/platform','Publisher trusted.');});
    $r->post('/platform/publisher/revoke',function(){Db::run('DELETE FROM platform_publishers WHERE public_key=?',[text_input('public_key',100)]);PlatformService::audit('publisher-revoked','Future packages require renewed trust.');return redirect('/platform','Publisher trust revoked. Disable any installed code separately.');});
    $r->post('/platform/plugin/preview',function(){$f=$_FILES['file']??[];if(($f['error']??1)!==UPLOAD_ERR_OK)throw new InvalidArgumentException(t('Choose a signed ZIP.'));$public=text_input('public_key',100);$signature=text_input('signature',200);$p=PluginTrustService::inspect($f['tmp_name'],$public,$signature);$_SESSION['platform_plugin']=['zip'=>base64_encode(file_get_contents($f['tmp_name'])),'public'=>$public,'signature'=>$signature,'hash'=>$p['sha256']];return View::render(__DIR__.'/views/plugin.php',['title'=>t('Review community plugin'),'plugin'=>$p]);});
    $r->post('/platform/plugin/install',function(){if(($_POST['trust_code']??'')!=='yes')throw new InvalidArgumentException(t('Explicitly approve execution of this publisher\'s code.'));$p=$_SESSION['platform_plugin']??throw new InvalidArgumentException(t('Preview a signed plugin first.'));$path=tempnam(sys_get_temp_dir(),'lifeos-plugin-');try{file_put_contents($path,base64_decode($p['zip']));PluginTrustService::install($path,$p['public'],$p['signature'],$p['hash']);}finally{unlink($path);}unset($_SESSION['platform_plugin']);return redirect('/platform','Plugin installed. Restart to discover its routes and migrations.');});
    $r->post('/platform/plugin/{id}/disable',function($p){$id=$p['id'];if(!preg_match('/^[A-Z][A-Za-z0-9]{2,39}$/D',$id)||!Db::one('SELECT name FROM platform_plugins WHERE name=?',[$id]))throw new InvalidArgumentException(t('Choose an installed community plugin.'));if(!is_dir(ROOT.'/app/Modules/'.$id)||file_exists(ROOT.'/app/Modules/'.$id.'.disabled'))throw new InvalidArgumentException(t('Plugin is already disabled.'));if(!rename(ROOT.'/app/Modules/'.$id,ROOT.'/app/Modules/'.$id.'.disabled'))throw new RuntimeException(t('Could not disable plugin.'));PlatformService::audit('plugin-disabled',$id);return redirect('/platform','Plugin disabled; its data remains.');});
};
